    }

    Column(Modifier.fillMaxSize().padding(horizontal = 12.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text("Проекты", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)
