        var value = bytes.toDouble() / 1024
        var unit = 0
        while (value >= 1024 && unit < units.lastIndex) {
            value /= 1024
            unit++
        }
        val text = if (value >= 100) String.format("%.0f", value) else String.format("%.1f", value)
        return "$text ${units[unit]}"
    }
}

