    /**
     * A cheap summary of the whole tree, used to notice that the agent, the
     * editor or a file imported from the phone changed something while the app was
     * looking at it. Names, sizes and mtimes only - no nodes are built, so it is
     * safe to run every couple of seconds.
     */
    fun fingerprint(root: File): String {
        if (!root.isDirectory) return "-"
        var hash = 1125899906842597L
        var count = 0
        val stack = ArrayDeque<File>()
        stack.addLast(root)
        while (stack.isNotEmpty() && count < MAX_NODES) {
            val dir = stack.removeLast()
            for (child in dir.listFiles().orEmpty()) {
                count++
                if (child.isDirectory && child.name !in SKIP_DIRS) stack.addLast(child)
                hash = hash * 31 + child.name.hashCode()
                hash = hash * 31 + child.length()
                hash = hash * 31 + child.lastModified()
            }
        }
        return "$count:${java.lang.Long.toHexString(hash)}"
    }

    /**
     * Everything [build] is a function of, in one comparable string.
     *
     * [fingerprint] alone describes the disk and knows nothing about what the
     * user asked to see, so opening a folder or typing in the filter looked like
     * "nothing changed" and the tree was never rebuilt - the row flipped to an
     * open-folder icon with no children under it. What the tree shows depends on
     * three things, so the stamp has to cover all three.
     */
    fun stamp(root: File, expanded: Set<String>, filter: TreeFilter): String = buildString {
        append(fingerprint(root))
        append('|')
        append(filter.query).append('�')
        append(filter.kind).append('�')
        append(filter.showHidden)
        append('|')
        expanded.sorted().forEach { append(it).append('') }
    }
}

