 (function (global) {
   'use strict';

   var bridge = global.__pr;
   var ROOT = bridge.root();

   function err(msg) { return new Error(msg); }
   function enoent(op, p) { return err("ENOENT: no such file or directory, " + op + " '" + p + "'"); }
   function isString(x) { return typeof x === 'string'; }

