+                    val entry = ZipEntry(file.relativeToOrNull(base)?.path ?: file.name)
+                    zos.putNextEntry(entry)
+                    if (file.isFile) zos.write(file.readBytes())
+                    zos.closeEntry()
+                }
+            }
