         /** `name`, `name@version`, `@scope/name`, `@scope/name@version`. */
         fun parseSpec(raw: String): PackageSpec? {
             val s = raw.trim()
             if (s.isEmpty()) return null
             val at = if (s.startsWith("@")) s.indexOf('@', 1) else s.indexOf('@')
             val name = if (at < 0) s else s.substring(0, at)
