            } catch (t: Throwable) { false }
        }
        method("fsAppend") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method false
            try {
                f.parentFile?.mkdirs()
                f.appendText(str(a, 1) ?: "", Charsets.UTF_8)
