        if (exit != 0) return MiniShell.Result(exit, text)

        // A spec is a comma-separated list of positions and inclusive ranges; an
        // open-ended range ("3-") runs to the end of the line or record.
        fun positions(spec: String, size: Int): List<IntRange> =
            spec.split(',').mapNotNull { part ->
                val p = part.trim()
                if (p.isEmpty()) return@mapNotNull null
                val range = p.split('-')
                when (range.size) {
                    1 -> p.toIntOrNull()?.let { it..it }
                    else -> {
                        val from = range[0].trim().toIntOrNull() ?: return@mapNotNull null
                        val toRaw = range[1].trim()
                        if (toRaw.isEmpty()) from..Int.MAX_VALUE else {
                            val to = toRaw.toIntOrNull() ?: return@mapNotNull null
                            if (to < from) return@mapNotNull null
                            from..to
                        }
                    }
                }
            }.mapNotNull { r -> if (size == 0) null else r.intersect(1..size).takeIf { it.isNotEmpty() } }

        val out = lines(text).map { line ->
            if (fieldsSpec != null) {
                val parts = if (delim != null) line.split(delim) else line.split("\\t")
                positions(fieldsSpec, parts.size)
                    .map { r -> parts.subList(r.first - 1, r.last).joinToString(delim ?: "\\t") }
                    .joinToString(delim ?: "\\t")
            } else {
                buildString {
                    for (r in positions(charsSpec!!, line.length)) {
                        for (i in r) append(line[i])
                    }
                }
            }
        }
        return MiniShell.Result(0, join(out))
    }

