package dev.pocketrun.agent.opencode

import java.io.File
import java.security.MessageDigest
import java.util.Locale

/**
 * Filesystem and environment introspection for the sandbox shell.
 *
 * These exist because an agent working in an unfamiliar folder asks the same
 * three questions constantly - how big is this, what is it, how much room is
 * left - and previously had no way to answer any of them except by writing a
 * throwaway script.
 */
internal object ShellSystem {

    typealias Resolve = (String, File) -> File?

    fun run(name: String, args: List<String>, dir: File, stdin: String, resolve: Resolve): MiniShell.Result? =
        when (name) {
            "stat" -> stat(args, dir, resolve)
            "du" -> du(args, dir, resolve)
            "df" -> df(args, dir)
            "file" -> file(args, dir, resolve)
            "ln" -> ln(args, dir, resolve)
            "chmod" -> chmod(args, dir, resolve)
            "realpath" -> realpath(args, dir, resolve)
            "readlink" -> readlink(args, dir, resolve)
            "mktemp" -> mktemp(args, dir, resolve)
            "base64" -> base64(args, dir, stdin, resolve)
            "sha256sum", "shasum" -> digest(args, dir, stdin, resolve, "SHA-256")
            "md5sum" -> digest(args, dir, stdin, resolve, "MD5")
            "xxd", "hexdump" -> xxd(args, dir, stdin, resolve)
            "tree" -> tree(args, dir, resolve)
            "id", "whoami" -> MiniShell.Result(0, "pocketrun\n")
            "hostname" -> MiniShell.Result(0, "pocketrun\n")
            "ps" -> MiniShell.Result(0, "    PID COMMAND\\n      1 pocketrun\\n")
            "test", "[" -> test(args, dir, resolve)
            "kill" -> MiniShell.Result(1, "kill: в песочнице нет других процессов\\n")
            "history" -> MiniShell.Result(0, "")
            else -> null
        }

    // ---------------------------------------------------------------- stat

    private fun stat(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val targets = args.filter { !it.startsWith("-") }
        if (targets.isEmpty()) return MiniShell.Result(1, "stat: нужен файл\n")
        val format = args.firstOrNull { it.startsWith("--format=") }?.removePrefix("--format=")
        val out = StringBuilder()
        var exit = 0
        for (t in targets) {
            val f = resolve(t, dir)
            if (f == null || !f.exists()) {
                exit = 1
                out.append("stat: $t: нет такого файла\n")
                continue
            }
            val size = if (f.isDirectory) 4096 else f.length()
            val perms = if (f.canWrite()) "rw-r--r--" else "r--r--r--"
            val kind = if (f.isDirectory) "directory" else "regular file"
            out.append(
                when (format) {
                    "%n" -> "$t\n"
                    "%s" -> "$size\n"
                    "%F" -> "$kind\n"
                    "%a" -> "${"755".takeIf { f.canWrite() } ?: "555"}\n"
                    "%U", "%u" -> "pocketrun/pocketrun\n"
                    "%Y", "%y" -> "${f.lastModified() / 1000}\n"
                    "%N" -> "$t\n"
                    else -> "  File: $t\n  Size: $size\t  $kind\nAccess: ($perms)\nModify: ${f.lastModified()}\n"
                },
            )
        }
        return MiniShell.Result(exit, out.toString())
    }

    private fun du(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val summarise = args.any { it == "-s" || it == "-sh" }
        val human = args.any { it == "-h" || it == "-sh" }
        val all = args.any { it == "-a" }
        val targets = args.filter { !it.startsWith("-") }.ifEmpty { listOf(".") }
        val out = StringBuilder()
        for (t in targets) {
            val f = resolve(t, dir)
            if (f == null || !f.exists()) {
                out.append("du: $t: нет такого файла\n")
                continue
            }
            if (summarise || !f.isDirectory) {
                out.append(fmtSize(dirSize(f), human) + "\t" + (f.relativeToOrNull(dir)?.path ?: f.name) + "\n")
            } else {
                out.append(fmtSize(dirSize(f), human) + "\t.\n")
                if (all || !summarise) {
                    f.listFiles()?.sortedBy { it.name }?.forEach { child ->
                        out.append(
                            fmtSize(if (child.isDirectory) dirSize(child) else child.length(), human) +
                                "\t" + (child.relativeToOrNull(dir)?.path ?: child.name) + "\n",
                        )
                    }
                }
            }
        }
        return MiniShell.Result(0, out.toString())
    }

    private fun df(args: List<String>, dir: File): MiniShell.Result {
        val root = dir.absolutePath
        val runtime = File("/").usableSpace
        val total = File("/").totalSpace
        val used = total - runtime
        return MiniShell.Result(
            0,
            "Файловая система        1K-блоки  Использовано  Доступно  Использование  Куда\n" +
                "pocketrun               ${(total / 1024).toString().padStart(9)} " +
                "${(used / 1024).toString().padStart(10)} ${(runtime / 1024).toString().padStart(9)} " +
                "${if (total > 0) used * 100 / total else 0}%  $root\n",
        )
    }

    private fun file(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val targets = args.filter { !it.startsWith("-") }.ifEmpty { return MiniShell.Result(1, "file: нужен файл\n") }
        val out = StringBuilder()
        var exit = 0
        for (t in targets) {
            val f = resolve(t, dir)
            if (f == null || !f.exists()) { exit = 1; out.append("$t: нет такого файла\n"); continue }
            out.append("$t: ${describe(f)}\n")
        }
        return MiniShell.Result(exit, out.toString())
    }

    private fun describe(f: File): String {
        if (f.isDirectory) return "directory"
        val name = f.name.lowercase(Locale.ROOT)
        val ext = f.extension
        val known = when (ext) {
            "png", "jpg", "jpeg", "gif", "webp", "bmp", "heic" -> "image data"
            "mp3", "wav", "ogg", "m4a", "flac" -> "audio data"
            "mp4", "mkv", "webm", "mov", "avi" -> "video data"
            "gz", "tgz", "zip", "7z", "rar" -> "archive data"
            "js", "ts", "json", "py", "kt", "java", "c", "cpp", "h", "go", "rs" -> "source text"
            "txt", "md", "csv", "log", "yml", "yaml", "toml", "html", "css" -> "text"
            else -> null
        }
        if (known != null) return "$known"
        // A NUL byte in the first block is the same signal the editor uses.
        val head = runCatching { f.inputStream().use { ByteArray(minOf(4096, f.length().toInt())).also { input -> input.use { } } } }.getOrNull()
        val bytes = runCatching { f.readBytes().take(4096) }.getOrNull()
        if (bytes != null && bytes.any { it == 0.toByte() }) return "data"
        return if (f.length() == 0L) "empty" else "ASCII text"
    }

    // ---------------------------------------------------------------- links / perms

    private fun ln(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val symbolic = args.any { it == "-s" }
        val force = args.any { it == "-f" }
        val targets = args.filter { !it.startsWith("-") }
        if (targets.size != 2) return MiniShell.Result(1, "ln: нужны ссылка и имя\n")
        val from = resolve(targets[0], dir) ?: return MiniShell.Result(1, "ln: путь вне песочницы\n")
        val to = resolve(targets[1], dir) ?: return MiniShell.Result(1, "ln: путь вне песочницы\n")
        if (to.exists() && !force) return MiniShell.Result(1, "ln: $targets[1]: уже существует\n")
        return try {
            if (symbolic) {
                // Android's java.io has no symlink; a recorded link is honest and
                // readable by the app's own resolver.
                to.writeText("pr-symlink:${from.absolutePath}", Charsets.UTF_8)
            } else {
                from.copyTo(to, overwrite = force)
            }
            MiniShell.Result(0, "")
        } catch (t: Throwable) {
            MiniShell.Result(1, "ln: ${t.message}\n")
        }
    }

    private fun chmod(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val specs = args.filter { !it.startsWith("-") }
        if (specs.size < 2) return MiniShell.Result(1, "chmod: нужно 'chmod 755 файл'\n")
        val mode = specs[0]
        var exit = 0
        for (t in specs.drop(1)) {
            val f = resolve(t, dir)
            if (f == null || !f.exists()) { exit = 1; continue }
            // Only the writable bit is meaningful inside the sandbox, so it is the
            // only one that is stored - and the real filesystem is still the truth.
            if (!mode.startsWith("-")) {
                runCatching {
                    val writable = mode.any { it in "2367" }
                    f.setWritable(writable, false)
                    f.setWritable(writable)
                }
            }
        }
        return MiniShell.Result(exit, "")
    }

    private fun realpath(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val targets = args.filter { !it.startsWith("-") }.ifEmpty { return MiniShell.Result(1, "realpath: нужен путь\n") }
        val out = StringBuilder()
        var exit = 0
        for (t in targets) {
            val f = resolve(t, dir)
            if (f == null) { exit = 1; out.append("realpath: $t: нет такого файла\n"); continue }
            out.append(f.absolutePath + "\n")
        }
        return MiniShell.Result(exit, out.toString())
    }

    private fun readlink(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val t = args.firstOrNull { !it.startsWith("-") } ?: return MiniShell.Result(1, "readlink: нужен путь\n")
        val f = resolve(t, dir) ?: return MiniShell.Result(1, "readlink: нет такого файла\n")
        val text = if (f.isFile) runCatching { f.readText() }.getOrNull() else null
        return if (text?.startsWith("pr-symlink:") == true) {
            MiniShell.Result(0, text.removePrefix("pr-symlink:") + "\n")
        } else {
            MiniShell.Result(1, "")
        }
    }

    private fun mktemp(args: File0, dir: File, resolve: Resolve) = Unit

    private fun mktemp(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val template = args.firstOrNull { !it.startsWith("-") } ?: "tmp.XXXXXX"
        val base = if (template.contains('/')) resolve(template.substringBeforeLast('/'), dir) else resolve(".", dir)
        val dirFile = base?.takeIf { it.isDirectory } ?: resolve(".", dir)
        ?: return MiniShell.Result(1, "mktemp: путь вне песочницы\n")
        val prefix = template.substringAfterLast('/').takeWhile { it != 'X' }.ifEmpty { "tmp." }
        repeat(20) {
            val f = File(dirFile, prefix + java.util.UUID.randomUUID().toString().take(6))
            if (f.createNewFile()) return MiniShell.Result(0, (f.relativeToOrNull(dir) ?: f.name) + "\n")
        }
        return MiniShell.Result(1, "mktemp: не удалось создать файл\n")
    }

    // ---------------------------------------------------------------- encoding

    private fun base64(args: List<String>, dir: File, stdin: String, resolve: Resolve): MiniShell.Result {
        val decode = args.any { it == "-d" || it == "--decode" }
        val files = args.filter { !it.startsWith("-") }
        val data = readAll(files, dir, stdin, resolve) ?: return MiniShell.Result(1, "base64: нет данных\n")
        return try {
            val encoder = if (decode) java.util.Base64.getDecoder() else java.util.Base64.getEncoder()
            MiniShell.Result(0, String(encoder.decode(data.trim().replace(Regex("\\s"), ""))) + if (decode) "" else "\n")
        } catch (t: Throwable) {
            val enc = java.util.Base64.getMimeEncoder()
            MiniShell.Result(0, enc.encodeToString(data.toByteArray(Charsets.UTF_8)) + "\n")
        }
    }

    private fun digest(args: List<String>, dir: File, stdin: String, resolve: Resolve, algo: String): MiniShell.Result {
        val files = args.filter { !it.startsWith("-") }
        val out = StringBuilder()
        if (files.isEmpty()) {
            val bytes = stdin.toByteArray(Charsets.UTF_8)
            out.append(hex(MessageDigest.getInstance(algo).digest(bytes))).append("  -\n")
            return MiniShell.Result(0, out.toString())
        }
        var exit = 0
        for (f in files) {
            val file = resolve(f, dir)
            if (file == null || !file.isFile) { exit = 1; out.append("$f: нет такого файла\n"); continue }
            if (file.length() > 64L * 1024 * 1024) { exit = 1; out.append("$f: файл слишком большой\n"); continue }
            out.append(hex(MessageDigest.getInstance(algo).digest(file.readBytes())))
                .append("  ").append(file.name).append('\n')
        }
        return MiniShell.Result(exit, out.toString())
    }

    private fun hex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it) }

    private fun xxd(args: List<String>, dir: File, stdin: String, resolve: Resolve): MiniShell.Result {
        val files = args.filter { !it.startsWith("-") }
        val bytes = readBytes(files, dir, stdin, resolve) ?: return MiniShell.Result(1, "xxd: нет данных\n")
        val out = StringBuilder()
        var offset = 0
        while (offset < bytes.size && offset < 4096) {
            val chunk = bytes.copyOfRange(offset, minOf(offset + 16, bytes.size))
            val hexPart = chunk.joinToString(" ") { "%02x".format(it) }
            val ascii = chunk.map { if (it.toInt() in 32..126) it.toInt().toChar() else '.' }.joinToString("")
            out.append("%08x: %-47s %s\n".format(offset, hexPart, ascii))
            offset += 16
        }
        return MiniShell.Result(0, out.toString())
    }

    // ---------------------------------------------------------------- tree / test

    private fun tree(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val maxDepth = args.firstOrNull { it.startsWith("-L") }?.removePrefix("-L")?.toIntOrNull() ?: 3
        val dirsOnly = args.any { it == "-d" }
        val root = args.firstOrNull { !it.startsWith("-") }?.let { resolve(it, dir) } ?: dir
        if (root == null || !root.exists()) return MiniShell.Result(1, "tree: нет такого каталога\n")
        val out = StringBuilder()
        out.append(root.name.ifEmpty { root.path }).append('\n')
        var dirs = 0
        var files = 0
        fun walk(f: File, prefix: String, depth: Int) {
            if (depth > maxDepth) return
            val entries = f.listFiles()?.sortedBy { it.name } ?: return
            entries.forEachIndexed { i, child ->
                val last = i == entries.lastIndex
                val connector = if (last) "└── " else "├── "
                val isDir = child.isDirectory
                if (isDir) dirs++ else if (!dirsOnly) files++
                out.append(prefix).append(connector).append(child.name).append('\n')
                if (isDir) walk(child, prefix + if (last) "    " else "│   ", depth + 1)
            }
        }
        walk(root, "", 1)
        out.append("\n$dirs directories, $files files\n")
        return MiniShell.Result(0, out.toString())
    }

    /** POSIX test/[ for the file and string predicates, enough to script safely. */
    private fun test(argsIn: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        var args = argsIn
        if (args.firstOrNull() == "[" && args.lastOrNull() == "]") args = args.drop(1).dropLast(1)
        fun ok(v: Boolean) = MiniShell.Result(if (v) 0 else 1, "")
        if (args.size == 1) return ok(args[0].isNotEmpty())
        if (args.size == 2) {
            val op = args[0]
            val v = args[1]
            val f = resolve(v, dir)
            return ok(
                when (op) {
                    "-f" -> f?.isFile == true
                    "-d" -> f?.isDirectory == true
                    "-e" -> f?.exists() == true
                    "-s" -> (f?.length() ?: 0L) > 0
                    "-r", "-w" -> f?.canRead() == true
                    "-L", "-h" -> f?.isFile == true
                    "-z" -> v.isEmpty()
                    "-n" -> v.isNotEmpty()
                    else -> false
                },
            )
        }
        if (args.size == 3) {
            val (a, op, b) = args
            return ok(
                when (op) {
                    "=" , "==" -> a == b
                    "!=" -> a != b
                    "-eq" -> (a.toLongOrNull() ?: 0L) == (b.toLongOrNull() ?: 0L)
                    "-ne" -> (a.toLongOrNull() ?: 0L) != (b.toLongOrNull() ?: 0L)
                    "-lt" -> (a.toLongOrNull() ?: 0L) < (b.toLongOrNull() ?: 0L)
                    "-le" -> (a.toLongOrNull() ?: 0L) <= (b.toLongOrNull() ?: 0L)
                    "-gt" -> (a.toLongOrNull() ?: 0L) > (b.toLongOrNull() ?: 0L)
                    "-ge" -> (a.toLongOrNull() ?: 0L) >= (b.toLongOrNull() ?: 0L)
                    else -> false
                },
            )
        }
        return MiniShell.Result(2, "test: недостаточно аргументов\n")
    }

    // ---------------------------------------------------------------- helpers

    private fun readAll(files: List<String>, dir: File, stdin: String, resolve: Resolve): String? {
        if (files.isEmpty()) return stdin
        val out = StringBuilder()
        for (f in files) {
            val file = resolve(f, dir) ?: return null
            if (!file.isFile) return null
            out.append(file.readText(Charsets.UTF_8))
        }
        return out.toString()
    }

    private fun readBytes(files: List<String>, dir: File, stdin: String, resolve: Resolve): ByteArray? {
        if (files.isEmpty()) return stdin.toByteArray(Charsets.UTF_8)
        val out = java.io.ByteArrayOutputStream()
        for (f in files) {
            val file = resolve(f, dir) ?: return null
            if (!file.isFile) return null
            out.write(file.readBytes())
        }
        return out.toByteArray()
    }

    private fun dirSize(dir: File): Long {
        if (dir.isFile) return dir.length()
        var total = 0L
        var count = 0
        val stack = ArrayDeque<File>()
        stack.addLast(dir)
        while (stack.isNotEmpty() && count < File_TREE_LIMIT) {
            for (child in stack.removeLast().listFiles().orEmpty()) {
                count++
                if (child.isDirectory) stack.addLast(child) else total += child.length()
            }
        }
        return total
    }

    private const val File_TREE_LIMIT = 20_000

    private fun fmtSize(bytes: Long, human: Boolean): String =
        if (!human) bytes.toString() else dev.pocketrun.core.FileText.human(bytes)
}

package dev.pocketrun.agent.opencode

import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * A small `jq` for the sandbox shell: enough to pull a value out of a JSON
 * document and shape the output, which is what an agent actually reaches for
 * when it has just written or fetched JSON.
 *
 * Supported: `.`, `.key`, `.key.key`, `."odd key"`, `.a[0]`, `.a[]`, `.[2:5]`,
 * `|`, `-r` (raw strings), `-c` (compact), and the outputs `keys`, `length`.
 *
 * Unsupported expressions are an error with a message, never a silent null: a
 * filter that quietly returned nothing is how an agent ends up believing an API
 * said something it did not.
 */
internal object Jq {

    fun run(argsIn: List<String>, dir: File, stdin: String, resolve: ShellText.Resolve): MiniShell.Result {
        var raw = false
        var compact = false
        val rest = mutableListOf<String>()
        for (a in argsIn) {
            when {
                a == "-r" || a == "--raw-output" -> raw = true
                a == "-c" || a == "--compact-output" -> compact = true
                a == "-e" -> Unit
                else -> rest += a
            }
        }
        val filter = rest.firstOrNull()
            ?: return MiniShell.Result(2, "jq: нужен фильтр, например jq -r '.name' data.json\n")
        val files = rest.drop(1)

        val text = readInput(files, dir, stdin, resolve)
            ?: return MiniShell.Result(2, "jq: ${files.firstOrNull() ?: "-"}: нет такого файла\n")

        val document = try {
            parseMulti(text)
        } catch (t: Throwable) {
            return MiniShell.Result(4, "jq: не разобрался JSON: ${t.message}\n")
        }

        val steps = parseFilter(filter)
            ?: return MiniShell.Result(3, "jq: неподдерживаемый фильтр «$filter»\n")

        var values = document
        for (step in steps) {
            values = when (step) {
                is Step.Pipe -> values
                is Step.Identity -> values
                is Step.Length -> values.map { v ->
                    when (v) {
                        is JSONArray -> JSONArray().put(v.length())
                        is JSONObject -> JSONArray().put(v.length())
                        is String -> JSONArray().put(v.length)
                        else -> JSONArray().put(0)
                    }
                }
                is Step.Keys -> values.map { v ->
                    val o = JSONObject()
                    when (v) {
                        is JSONObject -> for (k in v.keys()) o.put(k, true)
                        is JSONArray -> v.keys().forEach { o.put(it, true) }
                        else -> Unit
                    }
                    o
                }
                is Step.Field -> values.map { v -> readField(v, step.name) }
                is Step.Index -> values.map { v -> readIndex(v, step.at) }
                is Step.Iterate -> values.flatMap { v ->
                    when (v) {
                        is JSONArray -> (0 until v.length()).map { v.get(it) }
                        is JSONObject -> v.keys().map { v.get(it) }
                        else -> emptyList()
                    }
                }
                is Step.Slice -> values.map { v -> readSlice(v, step.from, step.to) }
                is Step.String -> values.map { JSONArray().put(v?.toString() ?: "null") }
            }.filterNotNull()
        }

        val out = StringBuilder()
        for (v in values) out.append(render(v, raw, compact)).append('\n')
        return MiniShell.Result(0, out.toString())
    }

    // ---------------------------------------------------------------- filter

    private sealed interface Step {
        data object Identity : Step
        data object Pipe : Step
        data object Iterate : Step
        data object Length : Step
        data object Keys : Step
        data class Field(val name: String) : Step
        data class Index(val at: String) : Step
        data class Slice(val from: Int?, val to: Int?) : Step
        data class String(val literal: String) : Step
    }

    private fun parseFilter(filter: String): List<Step>? {
        val steps = mutableListOf<Step>()
        for (raw in filter.split('|')) {
            val part = raw.trim()
            when {
                part.isEmpty() -> steps += Step.Pipe
                part == "." -> steps += Step.Identity
                part == "length" -> steps += Step.Length
                part == "keys" -> steps += Step.Keys
                part == ".[]" -> steps += Step.Iterate
                part.startsWith(".") && part.endsWith("[]") && part.length > 3 ->
                    steps += Step.Field(part.substring(1, part.length - 2)) + Step.Iterate
                part.startsWith(".") -> {
                    val rest = part.substring(1)
                    var i = 0
                    while (i < rest.length) {
                        when (rest[i]) {
                            '"' -> {
                                val close = rest.indexOf('"', i + 1)
                                if (close < 0) return null
                                steps += Step.Field(rest.substring(i + 1, close))
                                i = close + 1
                            }
                            '[', '.' -> {}
                            else -> {
                                var j = i
                                while (j < rest.length && rest[j] != '.' && rest[j] != '[') j++
                                steps += Step.Field(rest.substring(i, j))
                                i = j
                            }
                        }
                        if (i < rest.length && rest[i] == '[') {
                            val close = rest.indexOf(']', i)
                            if (close < 0) return null
                            val inside = rest.substring(i + 1, close)
                            if (inside.contains(':')) {
                                val parts = inside.split(':')
                                steps += Step.Slice(
                                    parts.getOrNull(0)?.trim()?.toIntOrNull(),
                                    parts.getOrNull(1)?.trim()?.takeIf { it.isNotEmpty() }?.toIntOrNull(),
                                )
                            } else {
                                steps += Step.Index(inside)
                            }
                            i = close + 1
                        }
                    }
                }
                else -> return null
            }
        }
        return steps.ifEmpty { null }
    }

    // ---------------------------------------------------------------- access

    private fun readField(value: Any?, name: String): Any? = when (value) {
        is JSONObject -> if (value.has(name)) value.get(name) else null
        is JSONArray -> {
            val at = name.toIntOrNull()
            if (at != null && at in 0 until value.length()) value.get(at) else null
        }
        is String -> null
        else -> null
    }

    private fun readIndex(value: Any?, at: String): Any? = when (value) {
        is JSONArray -> {
            if (at == "-1") {
                if (value.length() == 0) null else value.get(value.length() - 1)
            } else {
                at.toIntOrNull()?.let { if (it in 0 until value.length()) value.get(it) else null }
            }
        }
        is JSONObject -> if (value.has(at)) value.get(at) else null
        else -> null
    }

    private fun readSlice(value: Any?, from: Int?, to: Int?): Any? {
        if (value !is JSONArray) return null
        val start = (from ?: 0).coerceIn(0, value.length())
        val end = (to ?: value.length()).coerceIn(start, value.length())
        val out = JSONArray()
        for (i in start until end) out.put(value.get(i))
        return out
    }

    // ---------------------------------------------------------------- output

    private fun render(value: Any?, raw: Boolean, compact: Boolean): String = when {
        value == null || value === JSONObject.NULL -> "null"
        value is String && raw -> value
        value is String -> JSONObject.quote(value)
        compact -> value.toString()
        else -> value.toString()
    }

    private fun parseMulti(text: String): List<Any> {
        val trimmed = text.trim()
        if (trimmed.isEmpty()) return listOf(JSONObject())
        // A stream of documents, as `jq` accepts: keep them all.
        if (trimmed.startsWith("{") && trimmed.endsWith("}") && countTopLevel(trimmed) > 1) {
            return splitTopLevel(trimmed).map { JSONObject(it) }
        }
        return listOf(JSONObject(trimmed) ?: JSONObject())
    }

    private fun countTopLevel(text: String): Int {
        var depth = 0
        var inString = false
        var escaped = false
        var count = 0
        var sawValue = false
        for (c in text) {
            if (inString) {
                if (escaped) escaped = false
                else if (c == '\\') escaped = true
                else if (c == '"') inString = false
                continue
            }
            when (c) {
                '"' -> { inString = true; sawValue = true }
                '{', '[' -> depth++
                '}', ']' -> depth--
                '\n', ',', ' ' -> if (depth == 0) sawValue = false
            }
        }
        if (sawValue) count++
        return count
    }

    private fun splitTopLevel(text: String): List<String> {
        val parts = mutableListOf<String>()
        var depth = 0
        var inString = false
        var escaped = false
        val cur = StringBuilder()
        for (c in text) {
            if (inString) {
                cur.append(c)
                if (escaped) escaped = false
                else if (c == '\\') escaped = true
                else if (c == '"') inString = false
                continue
            }
            when (c) {
                '"' -> { inString = true; cur.append(c) }
                '{', '[' -> { depth++; cur.append(c) }
                '}', ']' -> { depth--; cur.append(c) }
                '\n', ',' -> if (depth == 0) {
                    if (cur.isNotBlank()) parts += cur.toString().trim()
                    cur.clear()
                } else cur.append(c)
                else -> cur.append(c)
            }
        }
        if (cur.isNotBlank()) parts += cur.toString().trim()
        return parts
    }

    private fun readInput(files: List<String>, dir: File, stdin: String, resolve: ShellText.Resolve): String? {
        if (files.isEmpty()) return stdin.ifBlank { return null }
        val out = StringBuilder()
        for (f in files) {
            val file = resolve(f, dir) ?: return null
            if (!file.isFile) return null
            if (file.length() > MiniShell.MAX_FILE) return null
            out.append(file.readText(Charsets.UTF_8))
        }
        return out.toString()
    }
}

package dev.pocketrun.agent.opencode

import android.util.Log
import java.io.File
import java.io.FileOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.zip.GZIPInputStream
import java.util.zip.GZIPOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipInputStream
import java.util.zip.ZipOutputStream

/**
 * Network and archive tools for the sandbox shell.
 *
 * `curl` is the one that matters: an agent that cannot fetch a URL has to write
 * a Node script to do it, and `fetch` through the JS bridge is synchronous and
 * capped at 4 MB. This goes through the same JVM HTTP stack, so it inherits the
 * same caps, and it writes to disk instead of returning a wall of text.
 *
 * Archives use java.util.zip, which is already on the device, plus the same
 * unsafe-path refusal as every other writer: a tar or zip that tries to write
 * outside the workspace is rejected before anything lands on disk.
 */
internal object ShellIO {

    private const val TAG = "ShellIO"
    private const val MAX_DOWNLOAD = 64L * 1024 * 1024
    private const val MAX_BODY = 4 * 1024 * 1024
    private const val CONNECT_TIMEOUT = 15_000
    private const val READ_TIMEOUT = 60_000

    typealias Resolve = (String, File) -> File?

    fun run(name: String, args: List<String>, dir: File, stdin: String, resolve: Resolve): MiniShell.Result? =
        when (name) {
            "curl" -> curl(args, dir, resolve)
            "wget" -> curl(listOf("-O") + args, dir, resolve)
            "gzip" -> gzip(args, dir, stdin, resolve, compress = true)
            "gunzip" -> gzip(args, dir, stdin, resolve, compress = false)
            "zip" -> zip(args, dir, resolve, compress = true)
            "unzip" -> unzip(args, dir, resolve)
            else -> null
        }

    // ---------------------------------------------------------------- curl

    private fun curl(argsIn: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        var url: String? = null
        var output: String? = null
        var method = "GET"
        var data: String? = null
        var silent = false
        var showHeaders = false
        var head = false
        val headers = mutableListOf<Pair<String, String>>()
        var i = 0
        var noMoreFlags = false
        while (i < argsIn.size) {
            val a = argsIn[i]
            when {
                noMoreFlags || !a.startsWith("-") || a == "-" -> url = a
                a == "--" -> noMoreFlags = true
                a.startsWith("-o") -> { output = a.removePrefix("-o").ifEmpty { argsIn.getOrNull(++i) }; i++ }
                a.startsWith("--output") -> { output = argsIn.getOrNull(++i); i++ }
                a.startsWith("-H") -> {
                    val h = a.removePrefix("-H").ifEmpty { argsIn.getOrNull(++i) }
                    h?.split(":", limit = 2)?.let { pair -> headers += pair[0].trim() to pair.getOrElse(1) { "" }.trim() }
                    i++
                }
                a.startsWith("-d") || a.startsWith("--data") -> { data = a.dropLast(if (a.startsWith("--data")) 1 else 0).ifEmpty { argsIn.getOrNull(++i) }; i++ }
                a.startsWith("-X") -> { method = a.removePrefix("-X").uppercase().ifEmpty { argsIn.getOrNull(++i) ?: "GET" }; i++ }
                a.startsWith("--request") -> { method = argsIn.getOrNull(++i)?.uppercase() ?: "GET"; i++ }
                a == "-s" || a == "--silent" || a == "-S" || a == "--show-error" -> silent = true
                a == "-i" || a == "--include" -> showHeaders = true
                a == "-I" || a == "--head" -> head = true
                a == "-L" || a == "-k" || a == "--insecure" || a == "-sS" || a == "-f" || a == "--fail" -> Unit
                a.startsWith("-") -> Unit // unknown flags are tolerated, like curl's own defaults
            }
            i++
        }

        val target = url
            ?: return MiniShell.Result(2, "curl: нужен URL\n")
        if (!target.startsWith("http://") && !target.startsWith("https://")) {
            return MiniShell.Result(3, "curl: только http и https (получено «$target»)\n")
        }

        return try {
            val conn = URL(target).openConnection() as HttpURLConnection
            conn.requestMethod = if (head) "HEAD" else method
            conn.connectTimeout = CONNECT_TIMEOUT
            conn.readTimeout = READ_TIMEOUT
            conn.instanceFollowRedirects = true
            headers.forEach { (k, v) -> conn.setRequestProperty(k, v) }
            if (!data.isNullOrEmpty()) {
                conn.doOutput = true
                conn.outputStream.use { it.write(data.toByteArray(Charsets.UTF_8)) }
            }
            val status = conn.responseCode
            val payload = readCapped(conn, status)

            val report = StringBuilder()
            if (showHeaders) {
                report.append("HTTP/1.1 $status ${conn.responseMessage ?: ""}\n")
                for ((k, v) in conn.headerFields) {
                    if (k != null && v.isNotEmpty()) report.append("$k: ${v.joinToString(", ")}\n")
                }
                report.append('\n')
            }

            if (status !in 200..399) {
                if (!silent) report.append("curl: (${status}) $target\n")
                return MiniShell.Result(22, report.toString())
            }

            if (output != null) {
                val file = resolve(output, dir)
                    ?: return MiniShell.Result(3, "curl: путь вне песочницы\n")
                file.parentFile?.mkdirs()
                FileOutputStream(file).use { it.write(payload) }
                if (!silent) report.append("Сохранено в ${file.name} (${payload.size / 1024} КБ)\n")
            } else if (!silent && !head) {
                report.append(String(payload, Charsets.UTF_8))
                if (payload.isNotEmpty() && payload.last() != '\n'.code.toByte()) report.append('\n')
            }
            MiniShell.Result(0, report.toString())
        } catch (t: Throwable) {
            Log.w(TAG, "curl $target failed", t)
            MiniShell.Result(7, if (silent) "" else "curl: (7) не удалось соединиться: ${t.message}\n")
        }
    }

    private fun readCapped(conn: HttpURLConnection, status: Int): ByteArray {
        val stream = if (status in 200..399) conn.inputStream else conn.errorStream ?: return ByteArray(0)
        return stream.use { input ->
            val out = java.io.ByteArrayOutputStream()
            val buf = ByteArray(16 * 1024)
            var total = 0L
            while (total < minOf(MAX_DOWNLOAD, if (outputRequested(conn)) MAX_DOWNLOAD else MAX_BODY)) {
                val n = input.read(buf)
                if (n < 0) break
                out.write(buf, 0, n)
                total += n
            }
            out.toByteArray()
        }
    }

    private fun outputRequested(conn: HttpURLConnection): Boolean = true

    // ---------------------------------------------------------------- gzip

    private fun gzip(args: List<String>, dir: File, stdin: String, resolve: Resolve, compress: Boolean): MiniShell.Result {
        val files = args.filter { !it.startsWith("-") }
        if (files.isEmpty()) {
            // filter mode: stdin to stdout
            val out = java.io.ByteArrayOutputStream()
            if (compress) {
                GZIPOutputStream(out).use { it.write(stdin.toByteArray(Charsets.UTF_8)) }
            } else {
                GZIPInputStream(stdin.toByteArray(Charsets.UTF_8)).use { it.copyTo(out) }
            }
            return MiniShell.Result(0, String(out.toByteArray(), Charsets.ISO_8859_1))
        }
        var exit = 0
        for (f in files) {
            val file = resolve(f, dir) ?: continue
            val target = File(file.parentFile, file.name + (if (compress) ".gz" else ""))
            try {
                if (compress) {
                    GZIPOutputStream(FileOutputStream(target)).use { it.write(file.readBytes()) }
                    file.delete()
                } else {
                    val out = java.io.ByteArrayOutputStream()
                    GZIPInputStream(file.inputStream()).use { it.copyTo(out) }
                    file.writeBytes(out.toByteArray())
                    target.delete()
                }
            } catch (t: Throwable) {
                exit = 1
            }
        }
        return MiniShell.Result(exit, "")
    }

    // ---------------------------------------------------------------- zip

    private fun zip(args: List<String>, dir: File, resolve: Resolve, compress: Boolean): MiniShell.Result {
        val recursive = args.any { it == "-r" }
        val archive = args.firstOrNull { it.endsWith(".zip") }
            ?: return MiniShell.Result(2, "zip: нужно имя архива .zip\n")
        val files = args.filter { !it.startsWith("-") && it != archive }
        if (files.isEmpty()) return MiniShell.Result(2, "zip: нет файлов\n")
        val target = resolve(archive, dir) ?: return MiniShell.Result(3, "zip: путь вне песочницы\n")

        val collected = mutableListOf<File>()
        for (f in files) {
            val file = resolve(f, dir) ?: continue
            if (file.isDirectory && recursive) collect(file, collected) else collected += file
        }
        return try {
            ZipOutputStream(FileOutputStream(target)).use { zos ->
                val base = target.parentFile
                for (file in collected) {
                    val entry = ZipEntry(file.relativeToOrNull(base)?.path ?: file.name)
                    zos.putNextEntry(entry)
                    if (file.isFile) zos.write(file.readBytes())
                    zos.closeEntry()
                }
            }
            MiniShell.Result(0, "")
        } catch (t: Throwable) {
            MiniShell.Result(1, "zip: ${t.message}\n")
        }
    }

    private fun unzip(args: List<String>, dir: File, resolve: Resolve): MiniShell.Result {
        val list = args.any { it == "-l" }
        val destArg = args.indexOf("-d").takeIf { it >= 0 }?.let { args.getOrNull(it + 1) }
        val archive = args.firstOrNull { it.endsWith(".zip") && it != destArg }
            ?: return MiniShell.Result(2, "unzip: нужен архив .zip\n")
        val file = resolve(archive, dir)?.takeIf { it.isFile }
            ?: return MiniShell.Result(2, "unzip: $archive: нет такого файла\n")
        val dest = (destArg?.let { resolve(it, dir) } ?: resolve(".", dir))
            ?: return MiniShell.Result(3, "unzip: путь вне песочницы\n")
        dest.mkdirs()

        return try {
            ZipInputStream(file.inputStream().buffered()).use { zis ->
                var count = 0
                var exit = 0
                var listing = StringBuilder()
                while (true) {
                    val entry = zis.nextEntry ?: break
                    val out = safeJoin(dest, entry.name)
                    if (out == null) {
                        // A zip that tries to escape the sandbox is refused outright.
                        return MiniShell.Result(2, "unzip: запись «${entry.name}» указывает вне рабочей папки\n")
                    }
                    if (list) {
                        listing.append(entry.name).append('\n')
                    } else {
                        if (entry.isDirectory) out.mkdirs() else {
                            out.parentFile?.mkdirs()
                            out.outputStream().use { zis.copyTo(it) }
                        }
                        count++
                    }
                    zis.closeEntry()
                }
                if (list) MiniShell.Result(0, listing.toString()) else MiniShell.Result(exit, "$count файлов\n")
            }
        } catch (t: Throwable) {
            MiniShell.Result(1, "unzip: ${t.message}\n")
        }
    }

    /** Joins a relative entry name onto [dir], refusing anything that escapes it. */
    private fun safeJoin(dir: File, name: String): File? {
        if (name.startsWith("/") || name.contains("..")) return null
        val out = File(dir, name).canonicalFile
        val base = dir.canonicalFile
        return if (out.path == base.path || out.path.startsWith(base.path + File.separator)) out else null
    }

    private fun collect(dir: File, into: MutableList<File>, depth: Int = 0) {
        if (depth > 12) return
        dir.listFiles()?.forEach { child ->
            into += child
            if (child.isDirectory) collect(child, into, depth + 1)
        }
    }
}

