                         else -> n
                     },
                 )
                 i += 2
                 continue
             }
             if (c == '%' && format.getOrNull(i + 1) == '%') { out.append('%'); i += 2; continue }
             if (c == '%') {
+                // Flags, width and precision come before the conversion character,
