```kotlin
private fun splitCommand(script: String, from: Int, delim: Char): Pair<List<String>, Int>? {
    val parts = mutableListOf<String>()
    val cur = StringBuilder()
    var i = from
    while (i < script.length) {
        val c = script[i]
        when {
            c == '\\' && i + 1 < script.length -> { cur.append(c).append(script[i + 1]); i += 2 }
            c == delim -> {
                parts += cur.toString(); cur.clear(); i++
                if (parts.size == 3) return parts to i
            }
            else -> { cur.append(c); i++ }
        }
    }
    parts += cur.toString()
    return parts to script.length
}
