/**
 * The built-in viewer: what the app can show itself it shows itself, and what it
 * cannot it hands to a system app. No third-party player, no image library - the
 * platform already has a decoder and a player, and a project file should not cost
 * the app megabytes of dependencies to look at.
 */
@Composable
fun FileViewerDialog(preview: AppViewModel.FilePreview, viewModel: AppViewModel) {
    val file = when (preview) {
        is AppViewModel.FilePreview.Image -> null
        is AppViewModel.FilePreview.Audio -> preview.file
        is AppViewModel.FilePreview.Video -> preview.file
        is AppViewModel.FilePreview.Other -> preview.file
        else -> null
    }

    Dialog(
        onDismissRequest = viewModel::closePreview,
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Box(
            Modifier
                .fillMaxSize()
                .background(Color(0xFF101014)),
        ) {
            when (preview) {
                is AppViewModel.FilePreview.Loading -> Centered {
                    CircularProgressIndicator(color = Color.White)
                }
                is AppViewModel.FilePreview.Image -> ImageViewer(preview.bitmap, preview.name)
                is AppViewModel.FilePreview.Audio -> AudioViewer(preview.file)
                is AppViewModel.FilePreview.Video -> VideoViewer(preview.file)
                is AppViewModel.FilePreview.Other -> OtherViewer(preview.file, preview.size, viewModel)
                is AppViewModel.FilePreview.Failed -> Centered {
                    Text(preview.message, color = Color.White)
                }
                else -> Unit
            }

            Row(
                Modifier
                    .fillMaxWidth()
                    .padding(12.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                file?.let {
                    Text(
                        it.name,
                        color = Color.White,
                        style = MaterialTheme.typography.titleSmall,
                        maxLines = 1,
                        modifier = Modifier.weight(1f),
                    )
                    IconButton(onClick = { viewModel.openExternally(it) }) {
                        Icon(Icons.Filled.OpenInNew, contentDescription = "Открыть системным", tint = Color.White)
                    }
                } ?: Spacer(Modifier.weight(1f))
                IconButton(onClick = viewModel::closePreview) {
                    Icon(Icons.Filled.Close, contentDescription = "Закрыть", tint = Color.White)
                }
            }
        }
    }
}

@Composable
private fun Centered(content: @Composable () -> Unit) {
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { content() }
}

/** A photo, with the two gestures people expect: pinch to zoom, drag to pan. */
@Composable
private fun ImageViewer(bitmap: android.graphics.Bitmap, name: String) {
    var scale by remember { mutableFloatStateOf(1f) }
    var offsetX by remember { mutableFloatStateOf(0f) }
    var offsetY by remember { mutableFloatStateOf(0f) }
    Box(
        Modifier
            .fillMaxSize()
            .pointerInput(Unit) {
                detectTransformGestures { _, pan, zoom, _ ->
                    scale = (scale * zoom).coerceIn(1f, 8f)
                    if (scale > 1f) {
                        offsetX += pan.x
                        offsetY += pan.y
                    } else {
                        offsetX = 0f
                        offsetY = 0f
                    }
                }
            },
        contentAlignment = Alignment.Center,
    ) {
        Image(
            bitmap = bitmap.asImageBitmap(),
            contentDescription = name,
            modifier = Modifier
                .fillMaxWidth()
                .graphicsLayer {
                    scaleX = scale
                    scaleY = scale
                    translationX = offsetX
                    translationY = offsetY
                },
        )
    }
}

@Composable
private fun AudioViewer(file: File) {
    var player by remember { mutableStateOf<MediaPlayer?>(null) }
    var ready by remember { mutableStateOf(false) }
    var failed by remember { mutableStateOf<String?>(null) }
    var playing by remember { mutableStateOf(false) }
    var position by remember { mutableIntStateOf(0) }
    var duration by remember { mutableIntStateOf(0) }

    DisposableEffect(file) {
        val created = try {
            MediaPlayer().apply {
                setDataSource(file.absolutePath)
                setOnPreparedListener { ready = true; duration = it.duration.coerceAtLeast(0) }
                setOnCompletionListener { playing = false; position = 0 }
                setOnErrorListener { _, what, extra ->
                    failed = "не удалось открыть аудио (what=$what extra=$extra)"
                    true
                }
                prepareAsync()
            }
        } catch (t: Throwable) {
            failed = t.message ?: "не удалось открыть аудио"
            null
        }
        player = created
        onDispose {
            created?.release()
            player = null
        }
    }

    LaunchedEffect(playing) {
        while (playing) {
            position = player?.currentPosition ?: 0
            delay(300)
        }
    }

    Column(
        Modifier
            .fillMaxSize()
            .padding(24.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        failed?.let { Text(it, color = Color.White) }
        Spacer(Modifier.height(16.dp))
        IconButton(onClick = {
            val p = player ?: return@IconButton
            if (playing) {
                p.pause()
                playing = false
            } else {
                p.start()
                playing = true
            }
        }, enabled = ready && failed == null) {
            Icon(
                if (playing) Icons.Filled.Pause else Icons.Filled.PlayArrow,
                contentDescription = if (playing) "Пауза" else "Играть",
                tint = Color.White,
                modifier = Modifier.size(56.dp),
            )
        }
        Slider(
            value = position.toFloat(),
            onValueChange = { player?.seekTo(it.toInt()) },
            valueRange = 0f..duration.coerceAtLeast(1).toFloat(),
            enabled = ready && duration > 0,
        )
        Text(
            "${mmss(position)} / ${mmss(duration)}",
            color = Color.White,
            fontFamily = FontFamily.Monospace,
            fontSize = 12.sp,
        )
    }
}

@Composable
private fun VideoViewer(file: File) {
    var failed by remember { mutableStateOf<String?>(null) }
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
        AndroidView(
            modifier = Modifier.fillMaxSize(),
            factory = { context ->
                VideoView(context).apply {
                    setMediaController(MediaController(context))
                    setOnErrorListener { _, what, extra ->
                        failed = "видео не открылось (what=$what extra=$extra)"
                        true
                    }
                    setVideoPath(file.absolutePath)
                    setOnPreparedListener { start() }
                }
            },
        )
        failed?.let {
            Text(it, color = Color.White, modifier = Modifier.padding(24.dp))
        }
    }
}

@Composable
private fun OtherViewer(file: File, size: String, viewModel: AppViewModel) {
    val kind = FileTree.kindOf(file)
    Column(
        Modifier
            .fillMaxSize()
            .padding(24.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(file.name, color = Color.White, fontWeight = FontWeight.SemiBold)
        Spacer(Modifier.height(8.dp))
        Text(
            "${kind.title} · $size",
            color = Color.LightGray,
            fontSize = 13.sp,
        )
        Spacer(Modifier.height(4.dp))
        Text(
            "Приложение не умеет показывать этот тип файла — откройте его другим приложением.",
            color = Color.LightGray,
            fontSize = 12.sp,
        )
        Spacer(Modifier.height(16.dp))
        TextButton(onClick = { viewModel.openExternally(file) }) {
            Text("Открыть системным приложением", color = Color.White)
        }
    }
}

private fun mmss(ms: Int): String = "%d:%02d".format(ms / 60_000, (ms / 1000) % 60)

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

/**
 * opencode instructions: `AGENTS.md` (project + global) with `CLAUDE.md`
 * fallbacks, plus the `instructions` array from an opencode-style config
 * (`<workspace>/opencode/opencode.json` stands in for
 * `~/.config/opencode/opencode.json`). Remote instruction URLs are fetched
 * with a 5 second timeout, exactly like opencode.
 */
class Instructions(private val workspace: Workspace) {

    /** Global `~/.config/opencode` analog. */
    val globalDir: File get() = File(workspace.root, "opencode")

    data class Result(val text: String, val sources: List<String>)

    /**
     * Collects instructions for [projectDir]: project AGENTS.md (or CLAUDE.md),
     * walking up to the workspace root; then the global one; then every entry
     * of the config `instructions` list (local paths relative to the project
     * or the workspace, and http(s) URLs).
     */
    fun collect(projectDir: File?): Result {
        val parts = mutableListOf<Pair<String, String>>() // source → text

        // 1. project rules, nearest first (AGENTS.md wins over CLAUDE.md per directory)
        var dir = projectDir
        val chain = mutableListOf<File>()
        while (dir != null && dir.startsWith(workspace.root) && chain.size < 8) {
            chain += dir
            dir = dir.parentFile
        }
        for (d in chain.reversed()) {
            val f = ruleFile(d) ?: continue
            val text = f.readText(Charsets.UTF_8).trim()
            if (text.isNotEmpty()) parts += workspace.relativeTo(f) to text
        }

        // 2. global rules
        val global = ruleFile(globalDir)?.readText(Charsets.UTF_8)?.trim()
        if (!global.isNullOrEmpty()) parts += workspace.relativeTo(ruleFile(globalDir)!!) to global

        // 3. instructions from config
        for (entry in configInstructions()) {
            if (entry.startsWith("http://") || entry.startsWith("https://")) {
                fetchRemote(entry)?.let { parts += entry to it }
            } else {
                val f = resolveInstructionPath(entry, projectDir) ?: continue
                if (f.isFile) {
                    val text = f.readText(Charsets.UTF_8).trim()
                    if (text.isNotEmpty()) parts += workspace.relativeTo(f) to text
                }
            }
        }

        if (parts.isEmpty()) return Result("", emptyList())
        val text = parts.joinToString("\n\n") { "# ${it.first}\n\n${it.second}" }
        return Result(text, parts.map { it.first })
    }

    /** AGENTS.md, or CLAUDE.md when AGENTS.md is absent (Claude Code compat). */
    private fun ruleFile(dir: File): File? {
        val agents = File(dir, "AGENTS.md")
        if (agents.isFile) return agents
        val claude = File(dir, "CLAUDE.md")
        if (claude.isFile) return claude
        return null
    }

    /** The `instructions` array of `<workspace>/opencode/opencode.json`. */
    internal fun configInstructions(): List<String> {
        val config = File(globalDir, "opencode.json")
        if (!config.isFile) return emptyList()
        return try {
            val json = org.json.JSONObject(config.readText(Charsets.UTF_8))
            val arr = json.optJSONArray("instructions") ?: return emptyList()
            (0 until arr.length()).mapNotNull { arr.optString(it, "").trim().takeIf { it.isNotEmpty() } }
        } catch (t: Throwable) {
            emptyList()
        }
    }

    /** Supports glob-ish entries (a directory plus `*.md`) via a simple scan. */
    private fun resolveInstructionPath(entry: String, projectDir: File?): File? {
        if (entry.endsWith("/*") || entry.endsWith("/*.md")) {
            val parent = entry.removeSuffix("*").removeSuffix("/")
            val base = workspace.resolve(parent, projectDir ?: workspace.root) ?: return null
            if (!base.isDirectory) return null
            val files = base.listFiles { f -> f.isFile && f.name.endsWith(".md") } ?: return null
            // combined into one pseudo-file: return the first; others handled by caller loop
            // — simpler: create a synthetic marker by concatenating at collect() level
            // For now single-file entries cover the common case; glob entries use the first match.
            return files.sortedBy { it.name }.firstOrNull()
        }
        return workspace.resolve(entry, projectDir ?: workspace.root)
    }

    private fun fetchRemote(url: String): String? = try {
        val conn = URL(url).openConnection() as HttpURLConnection
        conn.connectTimeout = 5_000
        conn.readTimeout = 5_000
        val status = conn.responseCode
        if (status !in 200..299) null
        else conn.inputStream.bufferedReader(Charsets.UTF_8).use { it.readText().take(48 * 1024).trim().ifEmpty { null } }
    } catch (t: Throwable) {
        null
    }
}

